def reconcile(ledger, snapshot, tol_crypto=1e-6):
    problems = []
    held = {p.symbol: p.qty for p in snapshot.positions}
    for sym, qty in ledger.quantities().items():
        tol = tol_crypto if "/" in sym else 0.0
        if abs(held.get(sym, 0.0) - qty) > tol:
            problems.append(f"{sym}: ledger {qty} vs broker {held.get(sym, 0.0)}")
    return problems
